// Declarations from `@solidjs/signals@2.0.0-rc.21`, reduced: `createSignal` `dist/types/signals.d.ts:302` (value form,
// options dropped), `createMemo` `:358` (options dropped, `SourceAccessor` as `Accessor`), `ComputeFunction` `:74`,
// `createEffect` `:427` (`EffectBundle` and options dropped), `flush` `dist/types/core/scheduler.d.ts:448-449`, `action`
// `dist/types/core/action.d.ts:78`.
export type Accessor<T> = () => T;
export type ComputeFunction<Prev, Next extends Prev = Prev> = (v: Prev) => PromiseLike<Next> | AsyncIterable<Next> | Next;
export type EffectFunction<Prev, Next extends Prev = Prev> = (v: Next, p?: Prev) => (() => void) | void;
export declare function createSignal<T>(value: Exclude<T, Function>): [Accessor<T>, (value: T) => T];
export declare function createMemo<T>(compute: ComputeFunction<undefined | NoInfer<T>, T>): Accessor<T>;
export declare function createEffect<const T>(compute: ComputeFunction<undefined | NoInfer<T>, T>, effectFn: EffectFunction<NoInfer<T>, T>): void;
export declare function flush(): void;
export declare function flush<T>(fn: () => T): T;
export declare function action<Args extends any[], Y, R>(genFn: (...args: Args) => Generator<Y, R, any> | AsyncGenerator<Y, R, any>): (...args: Args) => Promise<R>;
